   "title": "如何衡量你的站外推广效果？",
   "url": "https://www.woshipm.com/share/6479395.html",
   "summary": "粉丝今天上午问：公司打算做站外推广，暂定用品牌词搜索量是否增加、自己ABA排名来衡量效果，但总觉得光看这两个指标不太对劲。站外推广归因难、反馈路径长，到底该怎么科学评估？ 粉丝今天上午问：公司打算做站外推广，暂定用品牌词搜索量是否增加自己ABA排名来衡量效果，但总觉得光看这两个指标不太对劲。到底该怎么科学评估？(今天一整天都在外面，回来就着手写了这篇文章) 这位粉丝的困惑，相信很多卖家都有同感。 站外推广不像站内广告，点一下就能看到ACOS和转化率，数据反馈路径长、归因难，很多卖家投完后只能靠“感觉”来判断好不好。 今天这篇文章，我们就来系统聊聊：站外推广的效果，到底应该怎么衡量？ 一、只盯品",
