   "url": "https://www.woshipm.com/share/6476851.html",
   "summary": "品牌定位和品牌口号，分别解决说对和说好的问题。定位说用户价值，口号讲用户沟通，前者是做正确的事，后者是正确地做事。先有品牌，才有口号，策略是评判标准，创意是高效发挥，不要本末倒置。 品牌定位和品牌口号分别解决「说对」和「说好」的问题。 定位说用户价值，口号讲用户沟通。前者是做正确的事，后者是正确地做事。 定位和口号可能重合，关键是看定位是否具备沟通属性。 品牌口号，先是品牌，才是口号。 品牌是本质，明确自己的战场。口号是形式，找到更有杠杆的沟通方式。 二者是策略+创意的逻辑，策略是评判标准，创意是高效发挥，不要本末倒置。 接下来我将从「系统思维+极简逻辑+大白话形式+具体案例」的逻辑来拆解品牌",
