   "url": "https://techorange.com/2026/10/20/new-arms-race",
   "summary": "說到無人機改變戰爭，多數人想到烏俄戰爭。但各國政府與國防企業，正把目光轉向更隱密的戰場：海底。 各國為何砸錢發展海底無人載具？這些機器又真的能做到什麼？ 根據電信研究機構 TeleGeography 統計，截至 2026 年初，全球在役海纜總長超過 150 萬公里；衛星只占美國國際通訊容量的 0.37%，其餘幾乎都靠海纜。除了海纜，海底還有油氣管線，以及把離岸風電送上岸的電力電纜。英國智庫 Chatham House 資深研究員 Katja Bego 直言：「我們整個經濟都建立在這上面。」 問題是，這些設施相當脆弱。深海段的海纜大約只有澆花水管粗細，直接鋪在海床上。全球每年約有 200 起海纜",
   "date": "2026-10-20T01:33:14.000Z",
