   "summary": "DeepSeek V4.1-Flash-1017 建立在 552B MoE 底座上，ProgramBench 从 20.3 升到 29.1。「帕累托改进」不是单纯降价，而是靠更短轨迹减少无效调用；但对比的闭源模型并非最新版，结论要拆开看。 当一个模型能从一句需求出发，完成规划、编码、运行和调试，开发者最该问的已经不只是“它能不能做出来”，而是“它能以多低的成本、在多长的任务链路里稳定做出来”。 DeepSeek V4.1-Flash-1017 把这两个问题放在了一次更新里。它展示了可自由切换视角的故宫 3D 场景、网页赛车和 Godot 游戏复刻，也给出了比 GPT-6 更低的单任务成本数据。",
