   "summary": "DeepSeek V4.1-Flash-1017 在抬高代码与 Agent 任务成绩的同时，压缩了运行时间、输出长度与 Token 成本，也让 Harness 的多步骤执行与 Search、Fetch 外部信息通道更可用。 DeepSeek新模型发布，性能涨了费用降了，许愿式编程成真 做 Agent 开发时，模型能力和调用成本往往是一对很难同时优化的变量。想让任务跑得更完整，通常要接受更长的执行时间、更高的输出 Token 消耗，以及更多的工具调用；一旦压缩推理链路，又可能牺牲代码质量和任务成功率。 DeepSeek V4.1-Flash-1017 试图改写这个取舍。这个版本已同步到网页端、A",
