   "id": "4v4l76",
   "title": "FDE 最难的问题：你凭什么认为，这样做就能赚钱？",
   "url": "https://www.woshipm.com/ai/6480428.html",
   "summary": "陪跑一家 AI 原生 To C 企业一个多月、做完 20 多个项目课题后，作者复盘 FDE 最难的一关：凭什么认为这样做就能赚钱。文章讲清业产研一体化、课题推进，以及从验证走向生产的路径。 上半年我们做了一件事情，陪跑一家在 AI 原生进程上已经比较领先的 To C 互联网企业，针对其核心管理人员去做一些 AI 项目： 这家公司之前就做了两件事。一件是把中层管理人员进行了升级，管理人员都需要下场做业务。第二件是做了业产研的融合，让业务人员需要懂一些产研如何进行辅助业务效率、质量提升的思维，然后让产研去做一些业务工作，具备业务思维。 说实话，最开始接这个单的时候，我们知道这个情况，但是不知道他们",
