   "url": "https://techorange.com/2026/10/15/datasys-agentspace",
   "summary": "隨著全球供應鏈對碳排資訊的要求日益提高，企業面對的挑戰，已不只是交出產品碳足跡報告，更在於如何回應客戶減碳要求，同時兼顧產品成本與訂單獲利。鼎新數智發揮 ERP 企業營運數據優勢，以企業已在用的 ERP 為底，透過 Agent Space 跨職能 Agent 協作，串聯碳數據與 ERP 中的物料、採購、生產及訂單毛利資訊，協助企業辨識排放熱點、研擬減碳方案，並評估其對整體營運的影響，讓碳管理從資訊揭露進一步延伸至企業經營決策。 在 10 月 14 日至 16 日舉行的「2026 台灣國際淨零永續展」中，鼎新以「Agent Space 讓減碳看得見成效」為主題，於台北南港展覽館 1 館 4 樓 ",
