   "url": "https://techorange.com/2026/10/15/anthropic-source-control-redesigning",
   "summary": "AI Coding Agent（AI 程式開發代理）讓工程師寫程式的速度大幅提升，但如果程式碼產出快到連既有開發工具都難以負荷，會發生什麼事、又如何解決？AI 公司 Anthropic 就遇上了這個問題，稱甚至決定捨棄廣泛使用的 Git，自行打造新的版本控制系統 Scion。 類似的開發流程瓶頸，也開始出現在其他企業。哈佛大學研究人員 Fiona Chen 與 James Stratton 分析 718 家企業、約 3 億筆工程工作紀錄，發現導入 AI Coding Agent 後，程式碼產出增加約 30%，但程式碼從提交審查到完成合併的時間也增加約 49%，最終完成的軟體工作量則未出現統計上",
