   "summary": "卓越新聞獎基金會今天公布2026新聞志業特殊貢獻獎得獎人，以及第二十五屆卓越新聞獎十七個專業獎項的入選作品名單。今年卓新獎參賽總件數為769件，經過評審團37位委員一個多月的審閱討論後，共選出94件入選作品。除新聞志業特殊貢獻獎事先公布外，各獎項得獎名單將於11月17日頒獎典禮上揭曉。",
